import{_ as l,o as a,c as s,ag as i}from"./chunks/framework.D2veAa-g.js";const h=JSON.parse('{"title":"分页存储管理","description":"","frontmatter":{"title":"分页存储管理"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/分页存储管理.md","filePath":"综合知识/系统基础/操作系统/分页存储管理.md","lastUpdated":null}'),o={name:"综合知识/系统基础/操作系统/分页存储管理.md"};function r(e,t,d,n,c,p){return a(),s("div",null,[...t[0]||(t[0]=[i('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 分页存储原理（页号/页内地址/页表/物理块号）</li><li>[x] 页面置换算法（OPT/FIFO/LRU/淘汰原则）</li><li>[x] 快表与慢表</li><li>[x] 逻辑地址→物理地址转换计算</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="分页存储原理" tabindex="-1">分页存储原理 <a class="header-anchor" href="#分页存储原理" aria-label="Permalink to &quot;分页存储原理&quot;">​</a></h3><p><strong>逻辑页分为页号和页内地址</strong>，页内地址就是物理偏移地址，页号与物理块号并非按序对应，需查询页表得知页号对应的物理块号，再用物理块号 + 偏移地址 = 物理地址。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/Pasted%20image%2020230905232507.png" alt="分页存储"></p><ul><li>优点：利用率高，碎片小，分配及管理简单</li><li>缺点：增加了系统开销，可能产生抖动现象</li></ul><h3 id="页面置换算法" tabindex="-1">页面置换算法 <a class="header-anchor" href="#页面置换算法" aria-label="Permalink to &quot;页面置换算法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算法</th><th>原理</th><th>特点</th></tr></thead><tbody><tr><td><strong>最优算法 (OPT)</strong></td><td>选择未来最长时间内不被访问的页面置换</td><td>理论最优，无法实现，用于基准对比</td></tr><tr><td><strong>先进先出 (FIFO)</strong></td><td>先调入内存的页先被淘汰</td><td>可能产生抖动（分配的页数越多，缺页率反而越高）</td></tr><tr><td><strong>最近最少使用 (LRU)</strong></td><td>过去最少使用的页面被淘汰</td><td>基于局部性原理，效率高，不会抖动</td></tr><tr><td><strong>淘汰原则</strong></td><td>优先淘汰最近未访问的，其次淘汰最近未被修改的</td><td>—</td></tr></tbody></table><h3 id="快表" tabindex="-1">快表 <a class="header-anchor" href="#快表" aria-label="Permalink to &quot;快表&quot;">​</a></h3><p>快表是一块<strong>小容量的相联存储器（Cache）</strong>，按内容访问、速度块，存放当前访问最频繁的少数活动页面的页号。</p><ul><li><strong>快表</strong>：页表存于 Cache，访问 1 次 Cache + 1 次内存</li><li><strong>慢表</strong>：页表存于内存，需访问 2 次内存才能取出页</li></ul><h3 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h3><h4 id="逻辑地址转物理地址" tabindex="-1">逻辑地址转物理地址 <a class="header-anchor" href="#逻辑地址转物理地址" aria-label="Permalink to &quot;逻辑地址转物理地址&quot;">​</a></h4><p>某系统页面大小为 4K，进程页面变换表如下，逻辑地址为十六进制 1D16H，求物理地址。</p><table tabindex="0"><thead><tr><th>页号</th><th>物理块号</th></tr></thead><tbody><tr><td>0</td><td>1</td></tr><tr><td>1</td><td>3</td></tr><tr><td>2</td><td>4</td></tr><tr><td>3</td><td>6</td></tr></tbody></table><p>答案：<strong>3D16H</strong></p><p>解析：页面大小 4K → 页内偏移 12 位（2^12=4096）。1D16H 低 12 位 = D16H（偏移地址），高 4 位 = 1（逻辑页号）→ 对应物理块号 3 → 物理地址 = 3D16H。</p><h4 id="页面淘汰" tabindex="-1">页面淘汰 <a class="header-anchor" href="#页面淘汰" aria-label="Permalink to &quot;页面淘汰&quot;">​</a></h4><p>某进程 4 个页面（0~3），分配 3 个存储块，访问前页面 1 不在内存。根据状态位/访问位/修改位，淘汰哪个页面代价最小？</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20241021002739.png" alt="页面表"></p><p>答案：<strong>3</strong></p><p>解析：淘汰原则—优先淘汰最近未被访问的，再淘汰最近未被修改的。页 0、2、3 最近都被访问过，但只有页 3 最近未被修改，淘汰代价最小。</p><h2 id="练习题-1" tabindex="-1">练习题 <a class="header-anchor" href="#练习题-1" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q48] 分页存储</strong></p><p>分页存储管理中，地址转换需要读取（ ）。</p><ul><li>A. 链表</li><li>B. 段表</li><li>C. 页表</li><li>D. 段表+页表</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：分页管理中，逻辑地址→物理地址通过查页表完成。</p></div></details><hr><p><strong>[Q56] 缺页中断</strong></p><p>以下情况会触发缺页中断（Page Fault）的是（ ）。</p><ul><li>A. 进程访问的页在物理内存中</li><li>B. 进程访问的页被标记为只读</li><li>C. 进程访问的页既不在内存也不在磁盘</li><li>D. 进程访问的页不在物理内存但存在于磁盘</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：缺页=页不在内存但在磁盘，需要调入。A 正常访问；B 是保护异常；C 是非法访问。</p></div></details><hr><p><strong>[Q63] 物理地址</strong></p><p>在页式存储管理中，以下哪种地址类型用于程序运行时在内存中的实际定位（ ）。</p><ul><li>A. 逻辑地址</li><li>B. 物理地址</li><li>C. 虚拟地址</li><li>D. 相对地址</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：物理地址=内存中实际地址；逻辑地址/虚拟地址=程序中的地址，需转换。</p></div></details><hr><p><strong>[Q105] 缺页中断类型</strong></p><p>当CPU要访问的页面不在内存中时，会引发（1）中断，系统处理该中断的过程称为（2）。</p><ul><li>A. 外部中断</li><li>B. 内部中断</li><li>C. 软中断</li><li>D. 缺页中断</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：访问的页不在内存中→缺页中断（Page Fault）。</p></div></details><hr><p><strong>[Q106] 页面置换</strong></p><p>当CPU要访问的页面不在内存中时，会引发（1）中断，系统处理该中断的过程称为（2）。</p><ul><li>A. 页面置换</li><li>B. 页面调入</li><li>C. 地址变换</li><li>D. 页面分配</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：缺页中断的处理过程=页面置换（选一页换出，调入所需页）。</p></div></details>',48)])])}const m=l(o,[["render",r]]);export{h as __pageData,m as default};
